  `Budget_Type_Description` TEXT,
  PRIMARY KEY (`Budget_Type_Code`)
);

CREATE TABLE `Projects` (
  `Project_ID` NUMBER,
  `Project_Details` TEXT,
  PRIMARY KEY (`Project_ID`)
);

CREATE TABLE `Documents` (
  `Document_ID` NUMBER,
  `Document_Type_Code` TEXT REFERENCES `Ref_Document_Types`(`Document_Type_Code`),
  `Project_ID` NUMBER REFERENCES `Projects`(`Project_ID`),
  `Document_Date` TIME,
  `Document_Name` TEXT,
  `Document_Description` TEXT,
  `Other_Details` TEXT,
  PRIMARY KEY (`Document_ID`)
);

CREATE TABLE `Statements` (
  `Statement_ID` NUMBER REFERENCES `Documents`(`Document_ID`),
  `Statement_Details` TEXT,
  PRIMARY KEY (`Statement_ID`)
);

CREATE TABLE `Documents_with_Expenses` (
  `Document_ID` NUMBER REFERENCES `Documents`(`Document_ID`),
  `Budget_Type_Code` TEXT REFERENCES `Ref_Budget_Codes`(`Budget_Type_Code`),
  `Document_Details` TEXT,
  PRIMARY KEY (`Document_ID`)
);

CREATE TABLE `Accounts` (
  `Account_ID` NUMBER,
  `Statement_ID` NUMBER REFERENCES `Statements`(`Statement_ID`),
  `Account_Details` TEXT,
  PRIMARY KEY (`Account_ID`)
);

